with open(out, 'w') as f:
    f.write('{\n "note": ' + json.dumps(corpus['note']) + ',\n "playerDeny": ' + json.dumps(GM_ONLY) + ',\n "cases": [\n' + ',\n'.join('  ' + json.dumps(c, ensure_ascii=False) for c in cases) + '\n ]\n}\n')
